// smn.js — the smn-lab bench controllers and media, ported line-for-line to JavaScript
// for MuJoCo WASM. Every function names its Python original in smn-lab; the MJCF itself is
// NOT re-implemented here — it is generated by smn-lab's own builders (see gen_models.py).
// SPDX-License-Identifier: GPL-3.0-or-later (follows smn-lab)
import { buildCrawlerXml } from './crawler_xml.js';
export { buildCrawlerXml };

// ---- smn_lab/control.py :: OpponentBoard.commands -----------------------------------------
export class OpponentBoard {
  constructor(kp = 3.0, kd = 0.3, cmax = 1.5, cocontraction = 0.0) {
    this.kp = kp; this.kd = kd; this.cmax = cmax; this.coc = cocontraction;
  }
  commands(theta, thetaDot, thetaCmd, thetaDotCmd) {
    const tau = this.kp * (thetaCmd - theta) + this.kd * (thetaDotCmd - thetaDot);
    let ar = Math.min(Math.max(tau, 0), this.cmax);
    let al = Math.min(Math.max(-tau, 0), this.cmax);
    if (this.coc) { ar = Math.min(this.cmax, ar + this.coc); al = Math.min(this.cmax, al + this.coc); }
    return [ar, al, tau];
  }
}

// ---- smn_lab/control.py :: MessagingBeam.command (open-loop default, entrain = 0) -----------
// The bench experiments the playground reproduces (C0, gravity_locomotion, umwelt) all run the
// beam open-loop; the entrainment path (ledger 🟠) is deliberately not exposed.
export class MessagingBeam {
  constructor(nJoints, { amp = 0.6, freq = 0.8, phaseLag = 1.2, coupling = 4.0, turnGain = 0.8 } = {}) {
    this.n = nJoints; this.amp = amp; this.w = 2 * Math.PI * freq;
    this.phaseLag = phaseLag; this.coupling = coupling; this.turnGain = turnGain;
    this.phase = Float64Array.from({ length: this.n }, (_, i) => -phaseLag * i);
    this.msg = new Float64Array(this.n);
    this.cmd = new Float64Array(this.n);
  }
  command(dt, bias = 0.0) {
    const n = this.n, ph = this.phase, dphi = new Float64Array(n);
    for (let i = 0; i < n; i++) {
      let m = 0.0;
      if (i > 0) m += Math.sin((ph[i - 1] - ph[i]) - this.phaseLag);
      if (i < n - 1) m += Math.sin((ph[i + 1] - ph[i]) + this.phaseLag);
      this.msg[i] = m;
      dphi[i] = this.w + this.coupling * m;
    }
    for (let i = 0; i < n; i++) {
      ph[i] = ph[i] + dphi[i] * dt;
      this.cmd[i] = this.amp * Math.sin(ph[i]) + this.turnGain * bias;
    }
    return this.cmd;
  }
}

// ---- smn_lab/fields.py :: ScalarField.sample -------------------------------------------------
export class ScalarField {
  constructor(sources) { this.sources = sources; }      // [[x, y, amp, sigma], ...]
  sample(x, y) {
    let v = 0.0;
    for (const [sx, sy, a, s] of this.sources) {
      const r2 = (x - sx) ** 2 + (y - sy) ** 2;
      v += a * Math.exp(-r2 / (2 * s * s));
    }
    return v;
  }
}

// R (row-major 3x3 at xmat[9*b]) @ f
function rot(xmat, b, f0, f1, f2, out, o) {
  const k = 9 * b;
  out[o] = xmat[k] * f0 + xmat[k + 1] * f1 + xmat[k + 2] * f2;
  out[o + 1] = xmat[k + 3] * f0 + xmat[k + 4] * f1 + xmat[k + 5] * f2;
  out[o + 2] = xmat[k + 6] * f0 + xmat[k + 7] * f1 + xmat[k + 8] * f2;
}

// ---- smn_lab/crawler.py :: apply_anisotropic_drag (the viscous medium, C0) -------------------
// `buf` is a mujoco.DoubleBuffer(6): WASM out-parameters must live on the WASM heap.
export function applyAnisotropicDrag(mj, m, d, bodyIds, cLong, cTrans, cRot, buf) {
  const xfrc = d.xfrc_applied, xmat = d.xmat, OBJ = mj.mjtObj.mjOBJ_BODY.value;
  for (const b of bodyIds) {
    mj.mj_objectVelocity(m, d, OBJ, b, buf, 1);
    const res = buf.GetView();
    const wz = res[2], vx = res[3], vy = res[4];
    rot(xmat, b, -cLong * vx, -cTrans * vy, 0.0, xfrc, 6 * b);
    rot(xmat, b, 0.0, 0.0, -cRot * wz, xfrc, 6 * b + 3);
  }
}

// ---- smn_lab/crawler.py :: apply_ground_friction (gravity-set dry friction, terrestrial) ----
export function applyGroundFriction(mj, m, d, bodyIds, muLong, muTrans, g, eps, buf) {
  const xfrc = d.xfrc_applied, xmat = d.xmat, mass = m.body_mass, OBJ = mj.mjtObj.mjOBJ_BODY.value;
  for (const b of bodyIds) {
    const nf = mass[b] * g;
    mj.mj_objectVelocity(m, d, OBJ, b, buf, 1);
    const res = buf.GetView();
    const vx = res[3], vy = res[4];
    rot(xmat, b, -muLong * nf * vx / (Math.abs(vx) + eps), -muTrans * nf * vy / (Math.abs(vy) + eps), 0.0, xfrc, 6 * b);
    xfrc[6 * b + 3] = 0; xfrc[6 * b + 4] = 0; xfrc[6 * b + 5] = 0;
  }
}

// ---- smn_lab/medusa.py :: apply_medium (the pond: quadratic drag) ---------------------------
export function applyMedusaMedium(d, bodyIds, cQuad = 6.0, cLin = 0.4, axis = 2, axisGain = 2.0) {
  const qv = d.qvel, xfrc = d.xfrc_applied;
  for (let i = 0; i < bodyIds.length; i++) {
    const b = bodyIds[i], v0 = qv[3 * i], v1 = qv[3 * i + 1], v2 = qv[3 * i + 2];
    const s = Math.sqrt(v0 * v0 + v1 * v1 + v2 * v2), c = cLin + cQuad * s;   // = np.linalg.norm
    const g = [1, 1, 1]; g[axis] = axisGain;
    xfrc[6 * b] = -c * g[0] * v0; xfrc[6 * b + 1] = -c * g[1] * v1; xfrc[6 * b + 2] = -c * g[2] * v2;
    xfrc[6 * b + 3] = 0; xfrc[6 * b + 4] = 0; xfrc[6 * b + 5] = 0;
  }
}

// ====================================================================== simulations =========
// Parameters are the bench's, copied from the named experiment scripts.
export const BENCH = {
  // experiments/c0_crawler.py
  aquarium: { amp: 0.8, freq: 0.9, kp: 4.0, kd: 0.4, cmax: 2.5, cLong: 0.5, cTrans: 7.0, turnGain: 4.0, biasSign: -1.0 },
  // experiments/gravity_locomotion.py / umwelt_morphology.py (MU_TRANS = 3.0 = ratio 20)
  terrarium: { amp: 0.8, freq: 0.9, kp: 4.0, kd: 0.4, cmax: 2.5, muLong: 0.15, muTrans: 3.0, turnGain: 4.0, biasSign: -1.0 },
  // experiments/medusa_swim.py
  medusa: { period: 0.5, duty: 0.15, cmax: 13.0, cQuad: 9.0, cLin: 0.15, axisGain: 2.5 },
};

export const CRAWLER_KW = {
  aquarium: {},                                                            // c0_crawler.py: builder defaults
  terrarium: { gravity_on: false, joint_damping: 0.03, bend_limit_deg: 50.0 }, // gravity_locomotion.py
};

export class CrawlerSim {
  // habitat: 'aquarium' (viscous anisotropic drag) | 'terrarium' (gravity-set ground friction)
  // objects: [[x, y, r], ...] static cylinders (build_crawler_xml `objects`); walls: arena walls; touch: ventral skin
  constructor(mj, nSeg, habitat, { field = null, objects = [], walls = false, touch = false, terrain = null } = {}) {
    this.terrain = terrain;               // ground only: friction scale field, see Terrain below
    this.mj = mj; this.habitat = habitat; this.n = nSeg; this.P = BENCH[habitat];
    this.opts = { objects: objects.map(o => o.slice()), walls, touch };
    this.i = 0; this.t = 0; this.bias = 0;
    this.load(null);
    this.field = field;
    this.beam = new MessagingBeam(nSeg - 1, { amp: this.P.amp, freq: this.P.freq, turnGain: field ? this.P.turnGain : 0.8 });
    this.boards = this.ap.map(() => new OpponentBoard(this.P.kp, this.P.kd, this.P.cmax));
    this.res = new mj.DoubleBuffer(6);
  }
  xml() {
    return buildCrawlerXml({ n_seg: this.n, ...CRAWLER_KW[this.habitat], with_walls: this.opts.walls,
                             touch: this.opts.touch, objects: this.opts.objects });
  }
  // (re)compile the model; static geoms add no DOFs, so the state carries over exactly
  load(prev) {
    const mj = this.mj, m = mj.MjModel.from_xml_string(this.xml()), d = new mj.MjData(m);
    if (prev) {
      d.qpos.set(prev.d.qpos); d.qvel.set(prev.d.qvel); d.ctrl.set(prev.d.ctrl);
      d.qacc_warmstart.set(prev.d.qacc_warmstart); d.time = prev.d.time;
      prev.d.delete(); prev.m.delete();
    }
    this.m = m; this.d = d; this.dt = m.opt.timestep;
    const n = this.n;
    this.seg = [...Array(n).keys()].map(k => m.body(`seg${k}`).id);
    this.senseL = m.site('sense_L').id; this.senseR = m.site('sense_R').id;
    this.zL = [...Array(n).keys()].map(k => m.site(`seg${k}_L`).id);
    this.zR = [...Array(n).keys()].map(k => m.site(`seg${k}_R`).id);
    const jIds = [...Array(n - 1).keys()].map(k => m.jnt(`j${k + 1}`).id);
    this.jq = jIds.map(j => m.jnt_qposadr[j]); this.jv = jIds.map(j => m.jnt_dofadr[j]);
    this.ap = [...Array(n - 1).keys()].map(k => m.actuator(`m_j${k + 1}_p`).id);
    this.an = [...Array(n - 1).keys()].map(k => m.actuator(`m_j${k + 1}_n`).id);
    this.touchAdr = this.opts.touch ? [...Array(n).keys()].map(k => m.sensor_adr[m.sensor(`touch${k}`).id]) : null;
    mj.mj_forward(m, d);
  }
  setObjects(objects) { this.opts.objects = objects.map(o => o.slice()); this.load({ m: this.m, d: this.d }); }
  setWorld({ objects = this.opts.objects, walls = this.opts.walls } = {}) {
    this.opts.objects = objects.map(o => o.slice()); this.opts.walls = walls; this.load({ m: this.m, d: this.d });
  }
  setField(field) { this.field = field; this.beam.turnGain = field ? this.P.turnGain : 0.8; }
  step() {
    const { mj, m, d, P } = this;
    let bias = 0.0;
    if (this.field) {
      const sx = d.site_xpos, L = 3 * this.senseL, R = 3 * this.senseR;
      bias = P.biasSign * (this.field.sample(sx[L], sx[L + 1]) - this.field.sample(sx[R], sx[R + 1]));
    }
    this.bias = bias;
    const tc = this.beam.command(this.dt, bias);
    const qp = d.qpos, qv = d.qvel, ctrl = d.ctrl;
    for (let k = 0; k < this.n - 1; k++) {
      const [ar, al] = this.boards[k].commands(qp[this.jq[k]], qv[this.jv[k]], tc[k], 0.0);
      ctrl[this.ap[k]] = ar; ctrl[this.an[k]] = al;
    }
    if (this.habitat === 'aquarium') applyAnisotropicDrag(mj, m, d, this.seg, P.cLong, P.cTrans, 0.03, this.res);
    else if (!this.terrain) applyGroundFriction(mj, m, d, this.seg, P.muLong, P.muTrans, 9.81, 0.05, this.res);
    else {                                // uneven ground: the bench's law, applied per segment with a local coefficient
      const x = d.xpos;
      for (const b of this.seg) {
        const sc = this.terrain.scale(x[3 * b], x[3 * b + 1]);
        applyGroundFriction(mj, m, d, [b], P.muLong * sc, P.muTrans * sc, 9.81, 0.05, this.res);
      }
    }
    mj.mj_step(m, d);
    this.i += 1; this.t = this.i * this.dt;
  }
  bends() { const q = this.d.qpos; return this.jq.map(a => q[a]); }   // realized joint angles (proprioception)
  touchForces() {                       // ventral skin: per-segment contact force (sensordata)
    if (!this.touchAdr) return null; const sd = this.d.sensordata;
    return this.touchAdr.map(a => sd[a]);
  }
  head() { const b = 3 * this.seg[0]; return [this.d.xpos[b], this.d.xpos[b + 1]]; }
  dispose() { this.res.delete(); this.d.delete(); this.m.delete(); }
}

// ---- Uneven ground (playground extension, NOT on the bench) ------------------------------------
// A smooth friction-scale field: s(x, y) = exp(Σ a_i · exp(-r_i² / 2σ²)). a = ln 3 is a rough patch
// (3× the bench's friction), a = ln(1/3) a slick one. The anisotropy ratio is unchanged.
export class Terrain {
  constructor(blobs, sigma = 0.35) { this.blobs = blobs; this.sig = sigma; }
  scale(x, y) {
    let e = 0; const s2 = 2 * this.sig * this.sig;
    for (const [cx, cy, a] of this.blobs) e += a * Math.exp(-((x - cx) ** 2 + (y - cy) ** 2) / s2);
    return Math.exp(e);
  }
}

// ---- experiments/sweep_q1_modulation.py :: per-zone dual-port reafference (ledger: Q1 ✅) -------
// Each zone integrates its OWN sensed displacement; every WIN steps the body fits a local linear
// gradient from all its bilateral readings, predicts each zone's self-caused change (gradient · own
// displacement, scaled by a per-zone gain calibrated in the first T_LEARN s), and subtracts it.
// What is left is the change the zone attributes to the world. Differences from Q1, declared:
// no sensor/proprioceptive noise; the world is whatever this page's field is (Q1 used a linear slope).
export class ZoneWorld {
  constructor(sim, { win = 125, tLearn = 8.0 } = {}) {
    this.sim = sim; this.win = win; this.tLearn = tLearn; const N = sim.n;
    this.disp = new Float64Array(2 * N); this.scale = new Float64Array(N).fill(1);
    this.calNum = new Float64Array(N); this.calDen = new Float64Array(N);
    this.rPrev = null; this.buf = new sim.mj.DoubleBuffer(6);
  }
  // call once after every sim.step(); returns a frame every `win` steps (Q1's `i % WIN == 0`)
  afterStep() {
    const s = this.sim, mj = s.mj, N = s.n, OBJ = mj.mjtObj.mjOBJ_BODY.value, i = s.i - 1, DT = s.dt;
    for (let k = 0; k < N; k++) {                       // [start:dualport]
      mj.mj_objectVelocity(s.m, s.d, OBJ, s.seg[k], this.buf, 0);
      const v = this.buf.GetView();
      this.disp[2 * k] += v[3] * DT; this.disp[2 * k + 1] += v[4] * DT;
    }
    if (i % this.win !== 0) return null;
    const t = i * DT, F = s.field, sx = s.d.site_xpos;
    const r = new Float64Array(N), px = [], py = [], val = [];
    for (let k = 0; k < N; k++) {
      const xL = sx[3 * s.zL[k]], yL = sx[3 * s.zL[k] + 1], xR = sx[3 * s.zR[k]], yR = sx[3 * s.zR[k] + 1];
      const vL = F ? F.sample(xL, yL) : 0, vR = F ? F.sample(xR, yR) : 0;
      r[k] = 0.5 * (vL + vR); px.push(xL, xR); py.push(yL, yR); val.push(vL, vR);
    }
    const [, gx, gy] = lstsq3(px, py, val);
    let out = null;
    if (this.rPrev) {
      const dr = new Float64Array(N), res = new Float64Array(N);
      for (let k = 0; k < N; k++) {
        const basis = gx * this.disp[2 * k] + gy * this.disp[2 * k + 1];
        dr[k] = r[k] - this.rPrev[k];
        res[k] = dr[k] - this.scale[k] * basis;
        if (t < this.tLearn) { this.calNum[k] += dr[k] * basis; this.calDen[k] += basis * basis; }
      }
      if (t < this.tLearn) for (let k = 0; k < N; k++) if (this.calDen[k] > 1e-12) this.scale[k] = this.calNum[k] / this.calDen[k];
      out = { t, r, dr, res, learning: t < this.tLearn };
    }
    this.rPrev = r; this.disp.fill(0);
    return out;
  }
  dispose() { this.buf.delete(); }
}
// least squares for v ≈ a + b·x + c·y (normal equations; numpy lstsq to round-off)
function lstsq3(x, y, v) {
  let n = x.length, Sx = 0, Sy = 0, Sxx = 0, Sxy = 0, Syy = 0, Sv = 0, Sxv = 0, Syv = 0;
  for (let i = 0; i < n; i++) { Sx += x[i]; Sy += y[i]; Sxx += x[i] * x[i]; Sxy += x[i] * y[i]; Syy += y[i] * y[i]; Sv += v[i]; Sxv += x[i] * v[i]; Syv += y[i] * v[i]; }
  const A = [[n, Sx, Sy], [Sx, Sxx, Sxy], [Sy, Sxy, Syy]], b = [Sv, Sxv, Syv];
  const det = M => M[0][0] * (M[1][1] * M[2][2] - M[1][2] * M[2][1]) - M[0][1] * (M[1][0] * M[2][2] - M[1][2] * M[2][0]) + M[0][2] * (M[1][0] * M[2][1] - M[1][1] * M[2][0]);
  const D = det(A); if (Math.abs(D) < 1e-18) return [0, 0, 0];
  return [0, 1, 2].map(c => det(A.map((row, i) => row.map((a, j) => (j === c ? b[i] : a)))) / D);
}

export class MedusaSim {
  constructor(mj, spec) {
    this.mj = mj; this.P = BENCH.medusa; this.spec = spec;
    this.m = mj.MjModel.from_xml_string(spec.xml);
    this.d = new mj.MjData(this.m);
    this.dt = this.m.opt.timestep;
    this.bid = spec.pos.map((_, i) => this.m.body(`b${i}`).id);
    this.coronal = spec.coronal; this.i = 0; this.t = 0; this.stroke = false;
    mj.mj_forward(this.m, this.d);
  }
  step() {
    const { mj, m, d, P } = this, ctrl = d.ctrl;
    const t = this.i * this.dt;                         // t = i*DT, as in medusa_swim.py
    this.stroke = ((t % P.period) / P.period) < P.duty;
    ctrl.fill(0);
    if (this.stroke) for (const c of this.coronal) ctrl[c] = P.cmax;   // power stroke
    applyMedusaMedium(d, this.bid, P.cQuad, P.cLin, 2, P.axisGain);
    mj.mj_step(m, d);
    this.i += 1; this.t = this.i * this.dt;
  }
  com() {
    const x = this.d.xpos; let s = [0, 0, 0];
    for (const b of this.bid) { s[0] += x[3 * b]; s[1] += x[3 * b + 1]; s[2] += x[3 * b + 2]; }
    return s.map(v => v / this.bid.length);
  }
  dispose() { this.d.delete(); this.m.delete(); }
}
